"""Explain error state, boot metadata, setup and asm classification."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1761': ('빌린 상자를 돌려줬어도 출입 기록에 퇴실 표시를 하지 않았다면 정리가 모두 끝난 것은 아니에요. 컴퓨터도 메모리와 처리 상태를 따로 정리해야 해요.', '오류가 났을 때 건너뛰는 코드와 남는 상태를 추적합니다.', '진입 → 연결 실패 → goto ret → 목록 반납 → 반환을 그리고, 지나가지 않는 leave_runtime에 표시하세요.', ['이 수업은 프로젝트에 고정된 Linux v6.12 원문을 읽어요. 주소 연결을 뜻하는 mapping이 실패한 경우예요. 앞 수업의 임시 목록 할당 실패와 달리, 이미 kmsan_enter_runtime을 호출한 뒤에 오류가 나요.', '첫 번째 shadow 연결이 실패하면 err에 오류를 저장하고 goto ret로 이동해요. 두 번째 origin 연결은 시도하지 않아요. shadow 연결은 성공했지만 origin 연결이 실패해도 같은 ret 위치로 이동해요.', 'goto는 이름표가 붙은 위치로 바로 이동하는 명령이에요. 그 사이에 있는 코드를 자동으로 실행해 주지 않아요. 이 원문에서는 ret가 leave_runtime과 네 flush 호출보다 뒤에 있으므로 이 호출들을 건너뛰어요.', 'ret에는 임시 목록 두 개를 kfree로 반납하고 오류를 반환하는 코드만 있어요. runtime을 끝내는 leave_runtime은 이곳에 없어요. 메모리 목록이 반납됐다고 도구 처리 상태까지 자동으로 되돌아가지는 않아요.', '정상 상태 0에서 시작해 진입 때 1이 됐다고 생각해 보세요. 성공하면 종료 호출로 0이 되지만, 이 실패 경로에는 그 호출이 없어 1이 남는 흐름이에요. 이것은 해당 함수의 경로를 따라 본 결과이며 실제 장비에서 오류를 일으킨 실험은 아니에요.', '이 모습을 새 코드에서 따라 할 정리 방법으로 배우지는 마세요. 코드를 검토할 때는 목록 반납, 진입 상태 복구, 이미 만든 연결의 정리를 각각 확인해야 한다는 사례예요. 이 ret에는 연결을 되돌리는 호출도 없으므로 여기만 보고 전체 호출 과정의 복구가 끝났다고 단정할 수 없어요.'], [('이 고정 원문에서 주소 연결 실패로 goto ret를 실행하면 leave_runtime도 실행하나요?', ['네. goto가 중간의 종료 코드를 모두 실행해요', '아니요. 종료 호출보다 뒤의 ret로 바로 이동해요'], '정답은 두 번째예요. goto는 목표 위치로 곧장 이동해요. ret에 leave_runtime이 없으므로 이 실패 경로는 종료 호출을 건너뛰어요.'), ('임시 목록 두 개를 반납했으면 runtime 상태도 복구됐다고 볼 수 있나요?', ['아니요. 메모리 반납과 상태 복구를 따로 확인해야 해요', '네. kfree 하나가 모든 상태를 되돌려요'], '정답은 첫 번째예요. kfree는 지정한 메모리를 반납하는 함수예요. runtime 상태를 끝내는 별도 호출까지 대신해 주지는 않아요.')]), 'os1762': ('책의 일부만 읽더라도 그 부분이 걸친 종이는 모두 준비해야 해요. 메모리 검사표도 요청 범위를 포함하는 페이지 전체를 준비해요.', '페이지 경계에 범위를 맞추는 이유와 부팅 초기 할당을 이해합니다.', '페이지 크기 4096, 시작 4099, 끝 8197을 수직선에 표시하고 아래 계산의 4096과 12288을 함께 적으세요.', ['부팅은 컴퓨터가 운영체제를 시작하는 과정이에요. kmsan_init_alloc_meta_for_range는 부팅 때 확보한 메모리 범위에 검사 정보를 준비해요. shadow는 준비 상태표이고 origin은 원인 정보표예요.', '페이지는 메모리를 일정한 크기로 나눈 덩어리예요. 시작 주소가 페이지 중간에 있으면 PAGE_ALIGN_DOWN으로 해당 페이지의 첫 주소까지 내려요. 요청된 첫 바이트가 포함된 페이지를 빠뜨리지 않으려는 계산이에요.', '페이지 크기가 4096이고 시작이 4099라면 시작을 4096으로 내려요. 끝 주소가 8197이면 바뀐 시작에서 끝까지 길이는 8197 - 4096 = 4101이에요. 끝 주소는 요청 범위 바로 다음 주소로 생각하세요.', 'PAGE_ALIGN은 그 길이를 페이지 크기의 배수로 올려요. 4101은 4096 한 장에 안 들어가므로 8192로 올려 두 페이지를 준비해요. 준비 범위는 4096부터 12288 직전까지예요. 시작뿐 아니라 끝이 걸친 페이지도 포함해요.', 'memblock_alloc(size, PAGE_SIZE)를 두 번 호출해 shadow와 origin을 각각 준비해요. memblock은 부팅 초기 메모리를 관리하는 데 쓰여요. 이 예에서는 두 공간을 각각 8192바이트씩 요청하며, 시작 주소를 페이지 경계에 맞춰 달라고 해요.', '하나라도 확보하지 못하면 panic으로 정상 진행을 중단하는 오류 경로에 들어가요. 성공한 경우에는 각 데이터 페이지에 해당 shadow와 origin 페이지를 연결해요. 검사표 페이지 자체에는 별도의 shadow·origin 연결을 비워 두어요. 정상 주소 범위가 전달된다는 전제로 읽는 코드예요.'], [('페이지 크기 4096, 시작 4099, 끝 8197이면 검사 공간 하나에 몇 페이지를 준비하나요?', ['시작 페이지 하나만 준비해요', '두 페이지를 준비해요'], '정답은 두 번째예요. 시작을 4096으로 내리면 길이가 4101이에요. 이를 8192로 올리므로 4096바이트 페이지 두 개가 필요해요.'), ('부팅 때 필요한 검사 공간을 확보하지 못하면 조용히 성공으로 끝내나요?', ['아니요. panic 오류 경로로 가요', '네. 성공값 0을 반환하고 계속해요'], '정답은 첫 번째예요. 원문은 shadow나 origin이 없으면 panic을 호출해요. 앞의 동적 연결 함수가 -ENOMEM을 반환하는 방식과는 달라요.')]), 'os1763': ('학생 네 명에게 각자의 준비표와 기록표를 한 장씩 연결해 줘요. 이미 있는 종이를 짝지어 주는 일이지, 새 종이를 만드는 일은 아니에요.', '세 페이지 배열을 같은 번호끼리 연결하는 작업을 이해합니다.', 'data, shadow, origin 세 줄에 0~3번 칸을 그리고 같은 번호끼리 화살표로 연결하세요.', ['kmsan_setup_meta는 데이터 페이지와 검사 페이지의 관계를 설정해요. page는 데이터 페이지 배열, shadow는 준비 상태표 배열, origin은 원인 정보표 배열이에요. 배열은 같은 종류의 항목을 번호 순서대로 모아 놓은 것이에요.', '세 배열은 호출하기 전에 이미 준비되어 있어야 해요. 이 함수에는 새 메모리를 요청하는 할당 코드가 없어요. 받은 배열들을 순회하며 각 페이지에 연결 정보를 적어요.', '반복 횟수는 1 << order예요. 여기서는 1을 order번 두 배로 늘린 수로 생각하면 돼요. order가 2이면 1 → 2 → 4이므로 네 페이지를 처리해요. 번호 i는 0, 1, 2, 3을 지나가요.', '각 번호 i에서 먼저 shadow[i]와 origin[i] 자체의 검사 연결을 비워요. set_no_shadow_origin_page는 그 페이지의 shadow·origin 포인터를 NULL로 만드는 도우미예요. NULL은 여기서 연결 대상이 없다는 표시예요. 페이지 내용 전체를 지우거나 메모리를 반납하는 동작은 아니에요.', '그다음 page[i]에 shadow[i]와 origin[i]를 연결해요. 예를 들어 데이터 3번의 준비 상태는 shadow 3번으로, 원인 정보는 origin 3번으로 찾아갈 수 있어요. 모든 데이터 페이지를 0번 검사표에 연결하지 않아요.', 'C에서 &shadow[i]는 그 항목의 주소를 뜻해요. 포인터에 이 주소를 저장해 서로 찾아갈 길을 만드는 것이에요. 호출자는 order에 맞는 충분한 길이의 배열을 제공해야 해요. 네 칸을 처리하는데 두 칸만 준비해도 괜찮다고 볼 수는 없어요.'], [('kmsan_setup_meta가 하는 일은 무엇인가요?', ['새 검사 페이지 배열을 반드시 할당해요', '이미 받은 페이지 배열을 같은 번호끼리 연결해요'], '정답은 두 번째예요. 본문은 반복문과 포인터 설정으로 이루어져 있어요. 메모리를 확보하는 단계와 연결하는 단계를 구별하세요.'), ('order가 2일 때 데이터 page[3]은 어느 준비 상태표에 연결되나요?', ['shadow[3]에 연결돼요', '모든 페이지와 똑같이 shadow[0]에 연결돼요'], '정답은 첫 번째예요. 반복문은 각 i에서 &page[i]와 &shadow[i]를 짝지어요. 네 페이지를 처리하므로 번호 3도 포함돼요.')]), 'os1764': ('어떤 문에서 입장 대상인지 확인했다고 건물 안 모든 방이 안전하다고 증명한 것은 아니에요. 주소 분류 함수도 자신이 확인하는 조건까지만 판단해요.', '주소 분류의 두 조건과 전체 범위 검증의 차이를 이해합니다.', '설정 켜짐/꺼짐과 shadow 있음/없음을 표로 그리세요. 설정이 켜진 낮은 주소는 첫 조건에서 끝난다고 표시하세요.', ['asm은 CPU 명령을 직접 적는 어셈블리 코드를 가리켜요. is_bad_asm_addr는 이런 코드와 관련된 KMSAN 검사 표시를 할 주소인지 분류하는 도우미예요. true는 이 도우미가 처리 대상에서 제외할 주소라는 뜻이에요.', '먼저 사용자 프로그램의 주소 공간과 커널의 주소 공간이 겹치지 않는 기종 설정이 켜졌는지 봐요. 설정 이름은 CONFIG_ARCH_HAS_NON_OVERLAPPING_ADDRESS_SPACE예요. 이 조건이 켜진 경우에만 다음 숫자 비교로 사용자 범위를 걸러요.', '그때 주소를 숫자로 본 값이 TASK_SIZE보다 작으면 true를 반환해요. TASK_SIZE는 이 비교에서 사용자 주소 범위의 경계를 나타내요. 비교는 작다인 <이므로 경계와 정확히 같은 값은 이 첫 조건만으로 거르지 않아요.', '첫 조건에서 끝나지 않았다면 kmsan_get_metadata로 shadow 검사 정보가 있는지 물어요. 결과가 NULL이면 true, 검사 정보가 있으면 false를 반환해요. 첫 조건에서 이미 true를 반환했다면 이 조회는 실행하지 않아요.', 'size는 접근 길이, is_store는 쓰기인지 나타내는 인자 이름이에요. 하지만 이 함수 본문은 두 값을 사용하지 않아요. addr + size 같은 끝 주소 계산도 없어요. 이름만 보고 범위 전체를 검사한다고 생각하면 안 돼요.', 'false는 여기의 두 제외 조건에 걸리지 않았다는 뜻이에요. 모든 바이트가 유효하거나 쓰기 권한이 있거나 사용 중 계속 살아 있는 메모리라는 보장은 아니에요. 시작 주소의 검사 정보 조회와 실제 접근 전체의 올바름은 따로 살펴야 해요.'], [('이 함수는 size를 이용해 마지막 바이트 주소까지 검사하나요?', ['네. 모든 바이트를 직접 읽어 확인해요', '아니요. 본문에서 size를 사용하지 않아요'], '정답은 두 번째예요. 본문은 설정에 따른 주소 비교와 shadow 조회만 해요. 길이 인자가 있다는 이유만으로 전체 범위 검사를 한다고 볼 수 없어요.'), ('주소 공간 분리 설정이 켜졌고 주소가 TASK_SIZE보다 작으면 어떤 결과인가요?', ['첫 조건에서 true를 반환해 처리 대상에서 제외해요', '항상 안전한 커널 주소로 인정해요'], '정답은 첫 번째예요. 설정 조건과 숫자 비교가 모두 참이면 바로 돌아가요. 뒤의 shadow 조회까지 실행해서 결과를 바꾸지 않아요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_436.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
